import math

def search(k, a):
	lt = 0
	rt = len(a) - 1
	ans = -1
	while lt <= rt:
		mid = lt + (rt - lt) // 2
		if a[mid] > k:
			rt = mid - 1
		if a[mid] <= k:
			lt = mid + 1
			ans = mid
	return ans

def primes(n):
	l = set()
	while n % 2 == 0:
		l.add(2)
		n = n / 2
	for i in range(3, int(math.sqrt(n)) + 1, 2):
		while n % i == 0:
			l.add(i)
			n = n / i
	if n > 2:
		l.add(n)
	return l
for _ in range(int(input())):
	n = int(input())
	m = [int(i) for i in input().split()]
	pfs = {}
	for (ix, i) in enumerate(m):
		pf = primes(i)
		for p in pf:
			if p in pfs:
				pfs[p][0].append(i)
				pfs[p][1].append(ix)
			else:
				pfs[p] = [[i], [ix]]
	for pf in pfs:
		ps = pfs[pf][0].copy()
		ps.sort(reverse=True)
		for i in range(1, len(ps)):
			pfs[pf][0][i] = pfs[pf][0][i - 1] + pfs[pf][0][i]
			ps[i] = ps[i] + ps[i - 1]
		pfs[pf].append(ps)
	sm = m.copy()
	for i in range(1, n):
		sm[i] = sm[i] + sm[i - 1]
	q = int(input())
	for _ in range(q):
		(p, k) = [int(i) for i in input().split()]
		if p not in pfs:
			print(sm[k - 1])
		else:
			pt = search(k - 1, pfs[p][1])
			if pt == -1:
				ad = 0
				df = 0
			else:
				ad = pfs[p][2][pt]
				df = pfs[p][0][pt]
			print(sm[k - 1] - df + ad)
